import { Component, EventEmitter, Input, Output } from '@angular/core';
import { ModalidadMinistracionDocumento } from '../../../../models/modalidad.ministracion.documento';
import { ModalidadMinistracionDocumentoService } from '../../../../controllers/modalidad.ministracion.documento.service';
import { FormFieldService } from '../../../../shared/generic-form/form-field/form-field-service.service';
import { FormField, FormFieldComponent } from '../../../../shared/generic-form/form-field/form-field.component';

import { DocumentoService } from '../../../../controllers/documento.service';

const FORM_FIELDS:FormField[]=[
  {
    apiUrl:'api/documentos',
    placeholder:'Nombre de documento...',
    keyList:'id',
    keyDetalle:'nombre',
    key:'documento_id',
  },
  {
    key:'prioridad',
    options:['OBLIGATORIO','OPCIONAL'],
  }
]

@Component({
    selector: 'app-modalidad-ministracion-documento',
    imports: [
    FormFieldComponent
],
    templateUrl: './modalidad-ministracion-documento.component.html',
    styleUrl: './modalidad-ministracion-documento.component.css'
})
export class ModalidadMinistracionDocumentoComponent {
  @Input() documento!: ModalidadMinistracionDocumento&{id:number};
  @Output() onDelete= new EventEmitter()

  fields= FORM_FIELDS
  edit:boolean=false;
  isLoading:boolean=false
  isDeleting:boolean=false

  constructor(
    private modalidadMinistracionDocumentoController: ModalidadMinistracionDocumentoService,
    private formFieldService: FormFieldService,
    private documentoController: DocumentoService,
  ){}

  ngOnInit(){
    if(!this.documento.id) this.edit=true;
    this.formFieldService.setValues(this.fields,this.documento)
  }

  async save(){
    this.isLoading=true
    this.formFieldService.setModelValues(this.fields,this.documento)
    const res=await this.modalidadMinistracionDocumentoController.createOrUpdate(this.documento)
    if(res){
      this.documento.id=res.id
      this.documento.documentos= await this.documentoController.find(this.documento.documento_id,[],false)
      this.isLoading=false
      this.edit=false
    }
  }

  async delete(){
    this.isDeleting=true
    if(this.documento.id){
      const res = await this.modalidadMinistracionDocumentoController.switch(this.documento)
      if(res){
        this.onDelete.emit()
      }
      this.isDeleting=false
      return
    }
    this.onDelete.emit()
  }
}
