import { Component } from '@angular/core';
import { ProgramaApoyo } from '../../../models/programa.apoyo';
import { ProgramaApoyoService } from '../../../controllers/programa.apoyo.service';
import { ActivatedRoute, Router } from '@angular/router';
import { Form } from '../../../shared/generic-form/generic-form.component';
import { FormGroupComponent } from "../../../shared/generic-form/form-group/form-group.component";
import { ModalidadMinistracion } from '../../../models/modalidad.ministracion';
import { ModalidadMinistracionComponent } from "./modalidad-ministracion/modalidad-ministracion.component";

import { FormField, FormFieldComponent } from '../../../shared/generic-form/form-field/form-field.component';
import { FormFieldService } from '../../../shared/generic-form/form-field/form-field-service.service';

const FORM_DATA:Form=[
  {
    title:'Datos Del Apoyo',
    fields:[
      {
        label:'Nombre',
        key:'nombre',
        type:'text'
      },
      {
        label:'Alias',
        key:'alias',
        type:'text'
      },
      {
        label:'Vigencia',
        key:'vigencia',
        type:'date'
      },
    ]
  },
]

const FORM_FIELDS:FormField[]=[
  {
    label:'Nombre',
    key:'nombre',
    type:'text'
  },
  {
    label:'Alias',
    key:'alias',
    type:'text'
  },
  {
    label:'Vigencia',
    key:'vigencia',
    type:'date'
  },
]

@Component({
    selector: 'app-form-programa-apoyos',
    imports: [
    FormGroupComponent,
    ModalidadMinistracionComponent,
    FormFieldComponent
],
    templateUrl: './form-programa-apoyos.component.html',
    styleUrl: './form-programa-apoyos.component.css'
})
export class FormProgramaApoyosComponent {
  form:Form=FORM_DATA
  fields=FORM_FIELDS
  edit?:ProgramaApoyo
  modalidadesMinistraciones: ModalidadMinistracion[]=[]

  constructor(
    public controller: ProgramaApoyoService, 
    private route: ActivatedRoute,
    private formFieldService: FormFieldService,
  ){}

  ngOnInit(){
    this.formFieldService.resetValues(this.fields)
    this.checkIdParam()
  }

  async save(){
    if(!this.edit){
      this.edit={
        nombre: '',
        alias: '',
        vigencia: '',
        id: 0,
        deleted_at: null,
        created_at: '',
        updated_at: null
      }
    }
    this.formFieldService.setModelValues(this.fields,this.edit)
    this.edit=await this.controller.createOrUpdate(this.edit)
  }

  agregarModalidad(){
    this.modalidadesMinistraciones.push({
      programas_apoyo_id: this.edit!.id,
      monto_maximo: 0,
      modalidad_id: 1,
      usuario_id: 0,
      id: 0,
      deleted_at: null,
      created_at: '',
      updated_at: null
    })
  }

  copyOf(value:any){
    return JSON.parse(JSON.stringify(value))
  }

  private checkIdParam(){
    this.route.paramMap.subscribe(async (params)=>{
      if(params.get('id') && !isNaN(parseInt(params.get('id')??''))){
        const id= parseInt(params.get('id')!)
        if(this.edit && this.edit.id== id){
          return
        }
        
        this.edit= await this.controller.find(id,['modalidadesMinistraciones.modalidadesMinistracionesDocumentos.documentos','modalidadesMinistraciones.modalidades'],true)
        this.modalidadesMinistraciones= this.edit?.modalidades_ministraciones??[]
        this.formFieldService.setValues(this.fields,this.edit)
        console.log(this.edit)
      }
    })
  }
  
  public localDelete(modalidad:ModalidadMinistracion){
    this.modalidadesMinistraciones.splice(this.modalidadesMinistraciones.indexOf(modalidad),1)
  }
}
