import { Injectable } from '@angular/core';
import { FormField } from './form-field.component';

@Injectable({
  providedIn: 'root'
})
export class FormFieldService {

  constructor() { }

  resetValues(fields:FormField|(FormField[])){
    if(Array.isArray(fields)){
      fields.forEach((field)=>{
        field.value= undefined
      })
      return
    }
    fields.value= undefined
  }

  setValues(fields:FormField|(FormField[]),data:any){
    if(Array.isArray(fields)){
      fields.forEach((field)=>{
        field.value= data[field.key]
      })
      return
    }
    fields.value= data[fields.key]    
  }

  setModelValues(fields:FormField|(FormField[]),data:any){
    if(!data) return
    if(Array.isArray(fields)){
      fields.forEach((field)=>{
        if(data[field.key]!==undefined){
          data[field.key]= field.value
        }
      })
      return
    }
    data[fields.key]= fields.value
  }
}
