import { Component, EventEmitter, Input, Output } from '@angular/core';
import { ModalidadMinistracion } from '../../../../models/modalidad.ministracion';
import { ModalidadMinistracionService } from '../../../../controllers/modalidad.ministracion.service';
import { FormField, FormFieldComponent } from '../../../../shared/generic-form/form-field/form-field.component';
import { CurrencyPipe } from '@angular/common';
import { FormFieldService } from '../../../../shared/generic-form/form-field/form-field-service.service';
import { ButtonComponent } from "../../../../shared/button/button.component";
import { ModalidadMinistracionDocumento } from '../../../../models/modalidad.ministracion.documento';
import { ModalidadMinistracionDocumentoComponent } from "../modalidad-ministracion-documento/modalidad-ministracion-documento.component";
import { ModalidadService } from '../../../../controllers/modalidad.service';

const FORM_FIELDS: FormField[]=[
  {
    key:'monto_maximo',
    type:'number',
    placeholder:'Monto máximo permitido',
    validator:{
      min:0,
      required:true,
    }
  },
  {
    key:'modalidad_id',
    apiUrl:'api/modalidades',
    keyList:'id',
    keyDetalle:'nombre',
    validator:{
      required:true,
    }
  },
]

@Component({
    selector: 'app-modalidad-ministracion',
    imports: [
    FormFieldComponent,
    ButtonComponent,
    CurrencyPipe,
    ModalidadMinistracionDocumentoComponent
],
    templateUrl: './modalidad-ministracion.component.html',
    styleUrl: './modalidad-ministracion.component.css'
})
export class ModalidadMinistracionComponent {
  @Input() modalidad!: ModalidadMinistracion&{id:number}
  @Input() programa_apoyo_id:number=0
  @Output() onDelete= new EventEmitter()
  documentos: ModalidadMinistracionDocumento[]=[]
  fields= FORM_FIELDS

  showDetalles:boolean=false
  edit:boolean=false
  isLoading:boolean=false
  isDeleting:boolean=false

  constructor(
    private modalidadMinistracionController:ModalidadMinistracionService,
    private modalidadController: ModalidadService,
    private formFieldService: FormFieldService
  ){}

  ngOnInit(){
    if(this.modalidad.id===0) this.edit=true;
    this.formFieldService.setValues(this.fields,this.modalidad)
    this.documentos= this.modalidad.modalidades_ministraciones_documentos??[]
  }

  agregarDocumento(){
    this.documentos.push({
      documento_id: 0,
      modalidades_ministracion_id: this.modalidad.id,
      prioridad: 'OBLIGATORIO',
      usuario_id: 0,
      id: 0,
      deleted_at: null,
      created_at: '',
      updated_at: null
    })
    this.showDetalles=true
  }

  async save(){
    this.isLoading=true
    this.formFieldService.setModelValues(this.fields,this.modalidad)
    const res =await this.modalidadMinistracionController.createOrUpdate(this.modalidad)
    if(res){
      this.modalidad.id=res.id
      this.modalidad.modalidades= await this.modalidadController.find(this.modalidad.modalidad_id)
      this.isLoading=false
      this.edit=false
    }
  }

  async delete(){
    this.isDeleting=true
    if(this.modalidad.id){
      const res= await this.modalidadMinistracionController.switch(this.modalidad.id)
      if(res){
        this.onDelete.emit()
      }
      this.isDeleting=false
      return
    }
    this.onDelete.emit()
  }

  public localDelete(documento: ModalidadMinistracionDocumento){
    this.documentos.splice(this.documentos.indexOf(documento),1)
  }
}
